interfaces.interface:
Request: UserCreateDTO { email: string, password: string, full_name?: string, default_tenant_id: UUID, initial_role: RoleEnum, force_password_change?: boolean, is_active?: boolean }
Response: UserDetailDTO { id: UUID, email, is_active, default_tenant_id, default_tenant_name, roles: UserRoleDTO[], last_login, created_at, updated_at }
Errors: 409 Conflict (email exists), 400 Bad Request (validation), 403 Forbidden (RBAC), 500 Server Error

Request: UserUpdateDTO { email?: string, full_name?: string, default_tenant_id?: UUID, force_password_change?: boolean, is_active?: boolean }
Response: UserDetailDTO
Errors: 400 Bad Request (last super_admin), 403 Forbidden (RBAC), 404 Not Found, 409 Conflict (email exists)
